(1, '2026-05-08', 'fezadan-gunun-resmi-8-mayis-2026-page-from-tales-of-a-parrot-tuti-nama-text-page', 'Page from Tales of a Parrot (Tuti-nama): text page', 'Bilinmeyen Sanatçı', NULL, 'c. 1560', 'gum tempera, ink, and gold on paper', 'Array', 'https://openaccess-cdn.clevelandart.org/1962.279.142.a/1962.279.142.a_print.jpg', 'https://openaccess-cdn.clevelandart.org/1962.279.142.a/1962.279.142.a_web.jpg', 'Cleveland Museum of Art', '137450', 'https://clevelandart.org/art/1962.279.142.a', NULL, 'Tarih: c. 1560. Teknik: gum tempera, ink, and gold on paper. Eser Cleveland Museum of Art koleksiyonunda yer almaktadır.', 'template', NULL, 1, '2026-05-08 14:09:33'),
(2, '2026-05-09', 'fezadan-gunun-resmi-9-mayis-2026-painting-seven-from-album-of-paintings-by-haizan', 'Painting Seven from Album of Paintings by Haizan', 'Yoshitsugu Haizan (Japanese, 1846–1915)', NULL, 'late 1800s–early 1900s', 'page spread from double-sided accordion album; ink and color on paper', 'Array', 'https://openaccess-cdn.clevelandart.org/1997.247.h/1997.247.h_print.jpg', 'https://openaccess-cdn.clevelandart.org/1997.247.h/1997.247.h_web.jpg', 'Cleveland Museum of Art', '448486', 'https://clevelandart.org/art/1997.247.h', NULL, 'Sanatçı: Yoshitsugu Haizan (Japanese, 1846–1915). Tarih: late 1800s–early 1900s. Teknik: page spread from double-sided accordion album; ink and color on paper. Eser Cleveland Museum of Art koleksiyonunda yer almaktadır.', 'template', NULL, 1, '2026-05-09 03:12:10'),
(3, '2026-05-10', 'fezadan-gunun-resmi-10-mayis-2026-model-dish-from-a-foundation-depsoit', 'Model Dish from a Foundation Depsoit', 'Bilinmeyen Sanatçı', '', 'ca. 1479–1425 B.C.', 'Travertine (Egyptian alabaster), paint', 'Diam. 7 cm (1 15/16 in.)', 'https://images.metmuseum.org/CRDImages/eg/original/LC-32_2_20_EGDP027924.jpg', 'https://images.metmuseum.org/CRDImages/eg/web-large/LC-32_2_20_EGDP027924.jpg', 'Metropolitan Museum of Art', '557578', 'https://www.metmuseum.org/art/collection/search/557578', NULL, 'Tarih: ca. 1479–1425 B.C.. Teknik: Travertine (Egyptian alabaster), paint. Eser Metropolitan Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-10 00:53:14'),
(4, '2026-05-11', 'fezadan-gunun-resmi-11-mayis-2026-sacrificial-fire-from-the-tula-ram-bhagavata-purana', 'Sacrificial Fire, from the \"Tula Ram\" Bhagavata Purana', 'Bilinmeyen Sanatçı', NULL, 'c. 1720', 'Gum tempera, ink, and gold on paper', 'Array', 'https://openaccess-cdn.clevelandart.org/1990.40/1990.40_print.jpg', 'https://openaccess-cdn.clevelandart.org/1990.40/1990.40_web.jpg', 'Cleveland Museum of Art', '155592', 'https://clevelandart.org/art/1990.40', 'The evil king Kamsa organized a fire sacrifice in order to bring about the death of his brother-in-law, Vasudeva, father of the Hindu god incarnated as Krishna. The four-armed god of creation, Brahma, attends at the upper left with the sage, or holy man, Narada at the upper right.Scholars have linked the copious floral motifs throughout this dispersed series with textile patterns. This series was created in a port city, the center of flourishing international textile trade.', 'Tarih: c. 1720. Teknik: Gum tempera, ink, and gold on paper. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-11 11:34:47'),
(6, '2026-05-13', 'fezadan-gunun-resmi-13-mayis-2026-a-couple', 'A Couple', 'Hasegawa Sōen (Japanese)', NULL, 'late 1500s', 'hanging scroll; ink on paper', 'Array', 'https://openaccess-cdn.clevelandart.org/1985.133/1985.133_print.jpg', 'https://openaccess-cdn.clevelandart.org/1985.133/1985.133_web.jpg', 'Cleveland Museum of Art', '152251', 'https://clevelandart.org/art/1985.133', 'The person on the right holds a spray of chrysanthemums, while the other has daffodils suspended upside down from a stalk held over their shoulder.', 'Sanatçı: Hasegawa Sōen (Japanese). Tarih: late 1500s. Teknik: hanging scroll; ink on paper. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-13 02:35:17'),
(7, '2026-05-14', 'fezadan-gunun-resmi-14-mayis-2026-dr-james-stuart', 'Dr. James Stuart', 'Gilbert Stuart (American, 1755–1828)', NULL, 'c. 1815', 'oil on wood', 'Array', 'https://openaccess-cdn.clevelandart.org/1927.394.1/1927.394.1_print.jpg', 'https://openaccess-cdn.clevelandart.org/1927.394.1/1927.394.1_web.jpg', 'Cleveland Museum of Art', '109247', 'https://clevelandart.org/art/1927.394.1', NULL, 'Sanatçı: Gilbert Stuart (American, 1755–1828). Tarih: c. 1815. Teknik: oil on wood. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-14 03:25:28'),
(8, '2026-05-15', 'fezadan-gunun-resmi-15-mayis-2026-heavenly-king-virudhaka', 'Heavenly King Virudhaka', 'Bilinmeyen Sanatçı', NULL, '1368–1644', 'hanging scroll; color on silk', 'Array', 'https://openaccess-cdn.clevelandart.org/1918.544/1918.544_print.jpg', 'https://openaccess-cdn.clevelandart.org/1918.544/1918.544_web.jpg', 'Cleveland Museum of Art', '98870', 'https://clevelandart.org/art/1918.544', 'Virudhaka, Lokapala or Heavenly King of the South, is one of four guardians placed at the entrance of Buddhist temple halls or hung on all four sides of an altar for protection against evil spirits. Having a blue face, Virudhaka wears armor and holds a sword. Demons flank the deity: one with open mouth and three eyes whirls a banner and holds a snake; the other has a dragon slung around his neck.', 'Tarih: 1368–1644. Teknik: hanging scroll; color on silk. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-15 19:09:35'),
(9, '2026-05-17', 'fezadan-gunun-resmi-17-mayis-2026-album-of-daoist-and-buddhist-themes', 'Album of Daoist and Buddhist Themes', 'Bilinmeyen Sanatçı', NULL, '1200s', 'Album of fifty leaves; ink on paper', 'Array', 'https://openaccess-cdn.clevelandart.org/2004.1/2004.1_print.jpg', 'https://openaccess-cdn.clevelandart.org/2004.1/2004.1_web.jpg', 'Cleveland Museum of Art', '163105', 'https://clevelandart.org/art/2004.1', 'This extraordinary album has 50 paintings on a variety of religious subjects. They were likely created by several master craftsmen to share with studio apprentices as models for fulfilling commissions. The Jade Emperor and the Daoist pantheon make up the first 26 leaves. The next 14 leaves portray the Buddhist Ten Kings of Hell administering punishments to the dead. The third section, called “Clearing the Mountains,” features divine soldiers, led presumably by the deity Erlang Shen 二郎神, fighting undesirable creatures.', 'Tarih: 1200s. Teknik: Album of fifty leaves; ink on paper. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-17 00:42:25'),
(10, '2026-05-19', 'fezadan-gunun-resmi-19-mayis-2026-beauty-in-a-boat-on-sumida-river', 'Beauty in a Boat on Sumida River', 'Chōbunsai Eishi (Japanese, 1756–1829)', NULL, 'c. 1801–4', 'hanging scroll; ink and color on silk', 'Array', 'https://openaccess-cdn.clevelandart.org/1985.254/1985.254_print.jpg', 'https://openaccess-cdn.clevelandart.org/1985.254/1985.254_web.jpg', 'Cleveland Museum of Art', '152426', 'https://clevelandart.org/art/1985.254', 'The Sumida River was a popular refuge from the heat and humidity of the city during the summer. One can see the torii gate of Mimeguri Shrine just to the left of the woman\'s fan.', 'Sanatçı: Chōbunsai Eishi (Japanese, 1756–1829). Tarih: c. 1801–4. Teknik: hanging scroll; ink and color on silk. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-19 00:45:52'),
(11, '2026-05-20', 'fezadan-gunun-resmi-20-mayis-2026-madonna-of-humility', 'Madonna of Humility', 'Caterino Veneziano (Italian, active 1362–82)', NULL, 'late 1370s', 'tempera and gold on wood panel', 'Array', 'https://openaccess-cdn.clevelandart.org/1963.500/1963.500_print.jpg', 'https://openaccess-cdn.clevelandart.org/1963.500/1963.500_web.jpg', 'Cleveland Museum of Art', '139727', 'https://clevelandart.org/art/1963.500', 'The Madonna is shown seated on the ground as she nurses the infant Christ in a style of depiction called the \"Madonna (or Virgin) of Humility.\" This type of image shows Mary’s humility, or humilitas in Latin, sitting on the earth just with a cushion in contrast to her usual depiction with a throne. The virtue of humility was propagated especially by St. Francis of Assisi and found its way into painting since the 1350s in the wake of the Black Death.', 'Sanatçı: Caterino Veneziano (Italian, active 1362–82). Tarih: late 1370s. Teknik: tempera and gold on wood panel. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-20 16:57:42'),
(13, '2026-05-22', 'fezadan-gunun-resmi-22-mayis-2026-the-adoration-of-the-magi', 'The Adoration of the Magi', 'Bilinmeyen Sanatçı', NULL, 'c. 1424', 'tempera and gold on wood (oak)', 'Array', 'https://openaccess-cdn.clevelandart.org/1941.68.a/1941.68.a_print.jpg', 'https://openaccess-cdn.clevelandart.org/1941.68.a/1941.68.a_web.jpg', 'Cleveland Museum of Art', '120996', 'https://clevelandart.org/art/1941.68.a', 'This small winged altarpiece, called a triptych, was undoubtedly made for private use. The donor and his wife are shown in the lower central scene kneeling before the Virgin, her mother Saint Anne, and the Christ child. Above is the Epiphany with the Three Kings presenting gifts to a tightly swaddled Christ.', 'Tarih: c. 1424. Teknik: tempera and gold on wood (oak). Eser Cleveland Museum of Art koleksiyonundan seçilmiştir   ', 'manual', NULL, 1, '2026-05-22 14:55:45'),
(14, '2026-05-23', 'fezadan-gunun-resmi-23-mayis-2026-tradition', 'Tradition', 'Kenyon Cox (American, 1856–1919)', NULL, '1916', 'oil on canvas', 'Array', 'https://openaccess-cdn.clevelandart.org/1917.9/1917.9_print.jpg', 'https://openaccess-cdn.clevelandart.org/1917.9/1917.9_web.jpg', 'Cleveland Museum of Art', '98215', 'https://clevelandart.org/art/1917.9', 'This painting demonstrates Cox\'s ideas about the importance in art of tradition and the classical spirit. Two figures in Grecian costumes, representing the arts of the past, pass on the eternal flame of tradition to two figures in Renaissance dress. Literature wears the laurel crown, and Painting holds the palette. Born in Warren, Ohio, Cox studied art in Cincinnati and at the Pennsylvania Academy of Fine Arts in Philadelphia. In 1877, he moved to Paris to study under Carolus Duran (1838-1917) and Jean-Léon Gérôme (1824-1904). Five years later, Cox returned to New York where he established himself as a leader in the academic and conservative movement known as the American Renaissance. The artist achieved particular fame as a muralist; however by 1916, his health deteriorating, he turned his attention to paintings on canvas.', 'Sanatçı: Kenyon Cox (American, 1856–1919). Tarih: 1916. Teknik: oil on canvas. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-23 01:37:10'),
(15, '2026-05-24', 'fezadan-gunun-resmi-24-mayis-2026-yellow-chrysanthemums-and-red-osmanthus-in-the-style-of-wang-yuan', 'Yellow Chrysanthemums and Red Osmanthus in the Style of Wang Yuan', 'Shen Zhou (Chinese, 1427–1509)', NULL, '1468', 'hanging scroll, ink on paper', 'Array', 'https://openaccess-cdn.clevelandart.org/1997.100/1997.100_print.jpg', 'https://openaccess-cdn.clevelandart.org/1997.100/1997.100_web.jpg', 'Cleveland Museum of Art', '159724', 'https://clevelandart.org/art/1997.100', 'Shen Zhou, a native from Suzhou, was descended from a prominent land-owning family with strong ties to literati culture. Because Shen Zhou never entered government service, he had ample opportunity to cultivate the arts of painting, poetry, and calligraphy.Chrysanthemums and red osmanthus both bloom in autumn. The deep orange osmanthus flowers emanate a characteristically sweet fragrance. According to his inscription on the painting, Shen Zhou sought to imitate the style of the Yuan dynasty (1271–1368) painter Wang Yuan. His color-filled brushstrokes and washes, however, anticipate the flower painting style of Yun Shouping, whose Peonies are also in the Cleveland Museum of Art collection, https://www.clevelandart.org/art/1967.192. The sheer size and complex composition of this scroll are impressive.', 'Sanatçı: Shen Zhou (Chinese, 1427–1509). Tarih: 1468. Teknik: hanging scroll, ink on paper. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-24 05:13:13'),
(16, '2026-05-25', 'fezadan-gunun-resmi-25-mayis-2026-lions-and-tigers-in-peony-and-bamboo', 'Lions and Tigers in Peony and Bamboo', 'Yamaguchi Sekkei (Japanese, 1644–1732)', NULL, '1668', 'One of a pair of six-panel folding screens; ink and color on gilded paper', 'Array', 'https://openaccess-cdn.clevelandart.org/1972.10.1/1972.10.1_print.jpg', 'https://openaccess-cdn.clevelandart.org/1972.10.1/1972.10.1_web.jpg', 'Cleveland Museum of Art', '146212', 'https://clevelandart.org/art/1972.10.1', 'Sekkei lived and studied painting in Kyoto at the Kano school studio, the center of traditional painting activity in Japan since 1500. The use of gold foil as a backdrop for the frolicking animals served a practical as well as a decorative function. Because traditional Japanese rooms had no windows, interior lighting came from portable oil lamps and wax candles, whose effects were magnified by reflective surfaces.', 'Sanatçı: Yamaguchi Sekkei (Japanese, 1644–1732). Tarih: 1668. Teknik: One of a pair of six-panel folding screens; ink and color on gilded paper. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-25 20:32:46'),
(18, '2026-05-26', 'fezadan-gunun-resmi-26-mayis-2026-scenes-from-the-story-of-the-argonauts', 'Scenes from the Story of the Argonauts', 'Biagio d\'Antonio', 'Italian, Florentine, active by 1472–died 1516', '', 'Tempera on wood, gilt ornaments', 'Overall 24 1/8 x 60 3/8 in. (61.3 x 153.4 cm); painted surface 19 5/8 x 56 in. (49.8 x 142.2 cm)', 'https://images.metmuseum.org/CRDImages/ep/original/DP164778.jpg', 'https://images.metmuseum.org/CRDImages/ep/web-large/DP164778.jpg', 'Metropolitan Museum of Art', '435665', 'https://www.metmuseum.org/art/collection/search/435665', NULL, 'Sanatçı: Biagio d\'Antonio. Teknik: Tempera on wood, gilt ornaments. Eser Metropolitan Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-26 03:01:06'),
(19, '2026-05-27', 'fezadan-gunun-resmi-27-mayis-2026-text-folio-65-recto-from-a-kalpa-sutra', 'Text, Folio 65 (recto), from a Kalpa-sutra', 'Bilinmeyen Sanatçı', NULL, 'c. 1475–1500', 'Gum tempera, ink, and gold on paper', 'Array', 'https://openaccess-cdn.clevelandart.org/1932.119.65.a/1932.119.65.a_print.jpg', 'https://openaccess-cdn.clevelandart.org/1932.119.65.a/1932.119.65.a_web.jpg', 'Cleveland Museum of Art', '113053', 'https://clevelandart.org/art/1932.119.65.a', NULL, 'Tarih: c. 1475–1500. Teknik: Gum tempera, ink, and gold on paper. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-27 12:57:30'),
(20, '2026-05-31', 'fezadan-gunun-resmi-31-mayis-2026-the-brahman-s-predicament-is-conveyed-by-the-wind-to-the-fish-who-carries-the-news-to-the-king-of-the-ocean-from-a-tuti-nama-tales-of-a-parrot-eleventh-night', 'The Brahman’s predicament is conveyed by the wind to the fish who carries the news to the king of the Ocean, from a Tuti-nama (Tales of a Parrot): Eleventh Night', 'Bilinmeyen Sanatçı', NULL, 'c. 1560', 'gum tempera, ink, and gold on paper', 'Array', 'https://openaccess-cdn.clevelandart.org/1962.279.89.a/1962.279.89.a_print.jpg', 'https://openaccess-cdn.clevelandart.org/1962.279.89.a/1962.279.89.a_web.jpg', 'Cleveland Museum of Art', '137990', 'https://clevelandart.org/art/1962.279.89.a', 'A Brahman stands on a sandy beach prayerfully calling out for help to send a message to the king of the ocean. His own raja (sovereign) had sent him on pain of death to bring the king of the ocean to the Raja’s son’s wedding in three days. In the text, the wind brings the Brahman’s message to the ocean, and the fish, hearing it, take the news of the wedding invitation to their king. The swirling eddies and foamy shore suggest the presence of wind. Besides fish, a crocodile, sea snake, frog, and turtle also heed the message.', 'Tarih: c. 1560. Teknik: gum tempera, ink, and gold on paper. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-05-31 00:20:45'),
(21, '2026-06-01', 'fezadan-gunun-resmi-1-haziran-2026-page-from-tales-of-a-parrot-tuti-nama-text-page', 'Page from Tales of a Parrot (Tuti-nama): text page', 'Bilinmeyen Sanatçı', NULL, 'c. 1560', 'gum tempera, ink, and gold on paper', 'Array', 'https://openaccess-cdn.clevelandart.org/1962.279.2.b/1962.279.2.b_print.jpg', 'https://openaccess-cdn.clevelandart.org/1962.279.2.b/1962.279.2.b_web.jpg', 'Cleveland Museum of Art', '137573', 'https://clevelandart.org/art/1962.279.2.b', NULL, 'Tarih: c. 1560. Teknik: gum tempera, ink, and gold on paper. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-06-01 17:15:53'),
(22, '2026-06-02', 'fezadan-gunun-resmi-2-haziran-2026-seal', 'Seal', 'Bilinmeyen Sanatçı', '', '', 'Jade', 'H. 3 5/8 in. (9.2 cm); W. 3 5/8 in. (9.2 cm)', 'https://images.metmuseum.org/CRDImages/as/original/19_19_21_O1.jpg', 'https://images.metmuseum.org/CRDImages/as/web-large/19_19_21_O1.jpg', 'Metropolitan Museum of Art', '41003', 'https://www.metmuseum.org/art/collection/search/41003', NULL, 'Teknik: Jade. Eser Metropolitan Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-06-02 03:14:42'),
(23, '2026-06-03', 'fezadan-gunun-resmi-3-haziran-2026-the-monkeys-and-bears-fight-ravana-and-his-demons-verso-from-a-romance-of-chandrabhanu-and-lavanyavati-of-upendra-bhanja-indian-died-1740', 'The Monkeys and Bears Fight Ravana and His Demons (verso), from a Romance of Chandrabhanu and Lavanyavati of Upendra Bhanja (Indian, died 1740)', 'Bilinmeyen Sanatçı', NULL, 'late 1700s', 'Charcoal on palm leaf', 'Array', 'https://openaccess-cdn.clevelandart.org/1979.21.b/1979.21.b_print.jpg', 'https://openaccess-cdn.clevelandart.org/1979.21.b/1979.21.b_web.jpg', 'Cleveland Museum of Art', '149598', 'https://clevelandart.org/art/1979.21.b', 'This leaf from an 18th-century romance manuscript comes from a section of the book that retells the epic battle between the demon Ravana and the god-hero Rama. The 10-headed multiarmed demon Ravana is the second figure from the right. Rama’s army of monkeys and bears, wielding tree branches and clods of earth, fill the remainder of the leaf. The images were created using a stylus that incised into the palm leaf; charcoal was then rubbed over the leaf and wiped off, leaving only the incised areas in black.', 'Tarih: late 1700s. Teknik: Charcoal on palm leaf. Eser Cleveland Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-06-03 04:38:41'),
(24, '2026-06-04', 'fezadan-gunun-resmi-4-haziran-2026-gallery-of-fashion-vol-ii-april-1-1795-march-1-1796', 'Gallery of Fashion, vol.II: April 1 1795 - March 1, 1796', 'Nicolaus Heideloff', 'German, Stuttgart 1761–1837 The Hague', '1794–1802', 'Illustrations: etching and engraving (hand colored}', '13 3/8 x 10 7/16 x 1 15/16 in. (34 x 26.5 x 5 cm)', 'https://images.metmuseum.org/CRDImages/dp/original/DP889228.jpg', 'https://images.metmuseum.org/CRDImages/dp/web-large/DP889228.jpg', 'Metropolitan Museum of Art', '837923', 'https://www.metmuseum.org/art/collection/search/837923', NULL, 'Sanatçı: Nicolaus Heideloff. Tarih: 1794–1802. Teknik: Illustrations: etching and engraving (hand colored}. Eser Metropolitan Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-06-04 17:09:13'),
(25, '2026-06-05', 'fezadan-gunun-resmi-5-haziran-2026-bacchante-by-the-sea', 'Bacchante by the Sea', 'Camille Corot', 'French, Paris 1796–1875 Paris', '1865', 'Oil on wood', '15 1/4 x 23 3/8 in. (38.7 x 59.4 cm)', 'https://images.metmuseum.org/CRDImages/ep/original/DP-16590-001.jpg', 'https://images.metmuseum.org/CRDImages/ep/web-large/DP-16590-001.jpg', 'Metropolitan Museum of Art', '435963', 'https://www.metmuseum.org/art/collection/search/435963', NULL, 'Sanatçı: Camille Corot. Tarih: 1865. Teknik: Oil on wood. Eser Metropolitan Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-06-05 02:02:25'),
(26, '2026-06-06', 'fezadan-gunun-resmi-6-haziran-2026-medal', 'Medal', 'Friedrich Hagenauer', 'German, born Strasbourg, 1490–1500, died after 1546', '1543–44', 'Silver gilt, with traces of paint', 'Diameter: 1 3/8 in. (35 mm)', 'https://images.metmuseum.org/CRDImages/es/original/171227.jpg', 'https://images.metmuseum.org/CRDImages/es/web-large/171227.jpg', 'Metropolitan Museum of Art', '202444', 'https://www.metmuseum.org/art/collection/search/202444', NULL, 'Sanatçı: Friedrich Hagenauer. Tarih: 1543–44. Teknik: Silver gilt, with traces of paint. Eser Metropolitan Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-06-06 20:56:54'),
(27, '2026-06-07', 'fezadan-gunun-resmi-7-haziran-2026-venus-and-cupid', 'Venus and Cupid', 'Luca Cambiaso', 'Italian, Moneglia 1527–1585 Madrid', '1527–85', 'Pen and ink', '13 1/2 x 9 1/16 in.  (34.3 x 23.0 cm)', 'https://images.metmuseum.org/CRDImages/dp/original/DP808158.jpg', 'https://images.metmuseum.org/CRDImages/dp/web-large/DP808158.jpg', 'Metropolitan Museum of Art', '338334', 'https://www.metmuseum.org/art/collection/search/338334', NULL, 'Sanatçı: Luca Cambiaso. Tarih: 1527–85. Teknik: Pen and ink. Eser Metropolitan Museum of Art koleksiyonundan seçilmiştir.', 'template', NULL, 1, '2026-06-07 18:21:54');

